    coordinates: { lat: 48.8412, lng: 2.1613 },
    description: "Joséphine's beloved country retreat, where she cultivated roses—and where she died brokenhearted.",
    descriptionZh: "约瑟芬钟爱的乡间别墅，她在此培育玫瑰——也在此心碎而逝。",
    fullDescription: "Joséphine de Beauharnais bought Malmaison in 1799 while Napoleon was campaigning in Egypt, and it became the couple's intimate retreat and, briefly, a seat of government during the Consulate. Joséphine transformed the grounds into one of Europe's most celebrated gardens, importing exotic plants and assembling a rose collection painted by Pierre-Joseph Redouté. After Napoleon divorced her in 1809 for failing to bear an heir, she retired here in melancholy splendour and died at Malmaison on 29 May 1814, days after charming the visiting Tsar Alexander I. The house preserves her furniture and Napoleon's, a poignant time capsule of the Empire's private face.",
    fullDescriptionZh: "1799年拿破仑远征埃及时，约瑟芬·德·博阿尔内买下马尔梅松，这里成为夫妇俩的私密退隐之所，执政府时期还短暂充当政府所在地。约瑟芬将庭园打造成欧洲最负盛名的花园之一，引进异域植物，收集的玫瑰由雷杜德绘成画作。1809年拿破仑因她未能生育继承人而离婚后，她在忧郁的华丽中隐居于此，1814年5月29日在马尔梅松去世，去世前数日还款待了来访的沙皇亚历山大一世。宅邸保存着她与拿破仑的家具，是帝国私人面貌的动人时间胶囊。",
