    coordinates: { lat: 48.8462, lng: 2.3464 },
    description: "The secular temple where France buries its immortals—Voltaire, Hugo, the Curies, and Résistance heroes.",
    descriptionZh: "法国安葬其不朽者的世俗神殿——伏尔泰、雨果、居里夫妇与抵抗运动英雄。",
    fullDescription: "Commissioned by Louis XV as a church to Saint Geneviève and finished in 1790, the neoclassical Panthéon was swiftly converted by the Revolution in 1791 into a mausoleum for the nation's great citizens, inscribed 'Aux grands hommes la patrie reconnaissante'. Voltaire and Rousseau entered first; Victor Hugo's 1885 funeral drew two million mourners. Marie Curie, interred in 1995, was the first woman honoured for her own achievements. Resistance heroes Jean Moulin and, in 2015, four fighters including Germaine Tillion joined them. Beneath the dome, Foucault's pendulum famously demonstrated the Earth's rotation in 1851.",
    fullDescriptionZh: "先贤祠由路易十五下令建为圣热纳维耶芙教堂，1790年竣工，1791年大革命迅速将这座新古典建筑改为国家伟人的陵墓，铭刻着「祖国感激伟人」。伏尔泰与卢梭最先入祠；1885年雨果的葬礼吸引两百万送葬者。1995年入祠的居里夫人是首位因自身成就而受此殊荣的女性。抵抗运动英雄让·穆兰，以及2015年入祠的四位斗士（包括热尔梅娜·蒂利翁）也长眠于此。穹顶之下，傅科摆1851年著名地演示了地球自转。",
    historicalImage: "/images/locations/historical/pantheon-historical.jpg",
    modernImage: "/images/locations/pantheon.jpg",
