    descriptionZh: "中世纪欧洲的思想核心——也是1968年5月撼动法国的学生起义震中。",
    fullDescription: "Founded around 1257 by Robert de Sorbon, chaplain to Louis IX, the Sorbonne became the theology faculty of the University of Paris and one of Christendom's most influential intellectual authorities, weighing in on the trial of Joan of Arc and the great religious disputes of the Middle Ages. Cardinal Richelieu rebuilt its chapel in the 17th century and is entombed there. In May 1968 the Sorbonne became the flashpoint of a student uprising: its occupation triggered street battles in the Latin Quarter and a general strike of ten million workers that nearly toppled de Gaulle's government. The university carries the weight of eight centuries of French thought.",
    fullDescriptionZh: "索邦大学约1257年由路易九世的宫廷神父罗贝尔·德·索邦创立，成为巴黎大学神学院，是基督教世界最具影响力的学术权威之一，曾就贞德审判及中世纪重大宗教争议发声。红衣主教黎塞留于17世纪重建其礼拜堂并安葬于此。1968年5月，索邦成为学生起义的爆发点：占领校园引发拉丁区的街头搏斗和一千万工人的总罢工，几乎推翻戴高乐政府。这所大学承载着八个世纪法国思想的重量。",
