    year: "1871",
    coordinates: { lat: 48.8867, lng: 2.3431 },
    description: "The hilltop where the Paris Commune ignited—and where Picasso and Van Gogh remade modern art.",
    descriptionZh: "巴黎公社在此山丘点燃——毕加索与梵高在此重塑现代艺术。",
    fullDescription: "On 18 March 1871 the seizure of cannons stationed on the Butte Montmartre by government troops sparked the Paris Commune, a radical workers' uprising that ruled the city for seventy-two days before being crushed in the 'Bloody Week', when thousands of Communards were shot. The Basilica of Sacré-Cœur, begun in 1875, was built partly in atonement for that bloodshed. In the following decades the cheap-rent bohemian quarter drew Van Gogh, Toulouse-Lautrec, Renoir and, at the ramshackle Bateau-Lavoir studios, Picasso, who painted Les Demoiselles d'Avignon here in 1907—the birth of Cubism.",
    fullDescriptionZh: "1871年3月18日，政府军试图夺取蒙马特高地上的大炮，引发巴黎公社——一场激进的工人起义，统治巴黎七十二天后在「血腥周」被镇压，数千名公社社员被枪杀。1875年动工的圣心大教堂，部分是为那场血腥赎罪而建。随后数十年，租金低廉的波希米亚街区吸引了梵高、图卢兹-劳特累克、雷诺阿，以及在破旧的「洗衣船」工作室作画的毕加索，他1907年在此创作《亚维农的少女》——立体主义的诞生。",
