    description: "The fortress hillside where over a thousand Resistance fighters and hostages were shot by the Nazis.",
    descriptionZh: "堡垒山坡，逾千名抵抗运动战士与人质在此被纳粹枪决。",
    fullDescription: "During the German occupation of 1940–44, the western slope of the Mont Valérien fortress became the principal site of Nazi executions in the Paris region. In a forest clearing beside the fort, more than 1,000 Resistance fighters, communists, Jews and hostages were shot by firing squad, often in reprisal for attacks on German forces. Among the condemned, many wrote final letters later collected as a testament of the Resistance. In 1960 Charles de Gaulle inaugurated the Mémorial de la France Combattante here, its crypt holding sixteen fighters representing all who died for Free France. The bullet-scarred execution clearing is preserved as sacred ground.",
    fullDescriptionZh: "1940至1944年德国占领期间，瓦莱里安山堡垒的西坡成为巴黎地区纳粹处决的主要地点。在堡垒旁的林间空地，逾千名抵抗运动战士、共产党人、犹太人和人质被行刑队枪决，往往是对袭击德军的报复。许多被处决者写下遗书，后来汇编为抵抗运动的见证。1960年戴高乐在此揭幕「战斗法兰西纪念堂」，其地下墓室安放十六名代表所有为自由法国献身者的战士。弹痕累累的行刑空地作为圣地保留至今。",
