    name: "Omaha Beach",
    nameZh: "奥马哈海滩",
    type: "historical",
    region: "France",
    year: "1944",
    coordinates: { lat: 49.3697, lng: -0.8756 },
    description: "The bloodiest D-Day beach, where American soldiers fell in waves against a fortified cliff.",
    descriptionZh: "D日最血腥的海滩，美军士兵一波波倒在设防的悬崖之下。",
    fullDescription: "On the morning of 6 June 1944 the US 1st and 29th Infantry Divisions assaulted a five-mile crescent of sand codenamed Omaha, the most heavily defended of the five D-Day beaches. Rough seas swamped landing craft and DD tanks; German gunners in bluff-top bunkers cut down the first waves as ramps dropped. By nightfall Americans had suffered some 2,400 casualties here—more than on any other beach—yet clawed inland to secure the shore. 'Bloody Omaha' became the epitome of D-Day's cost. The wide tidal flats, still marked by remnants of the Mulberry and bunkers, stretch quietly below the American cemetery at Colleville.",
    fullDescriptionZh: "1944年6月6日清晨，美军第1和第29步兵师突击代号奥马哈的五英里新月形沙滩，这是五个D日海滩中防守最严密的。汹涌的海浪淹没登陆艇和两栖坦克；德军机枪手在崖顶碉堡中，趁登陆跳板放下时扫倒最初几波士兵。到夜幕降临，美军在此伤亡约2400人——超过任何其他海滩——却仍向内陆挺进，守住了滩头。「血腥奥马哈」成为D日代价的缩影。宽阔的潮间带至今留有桑葚港与碉堡残迹，静静延伸在科尔维尔美军公墓之下。",
