    fullDescription: "At dawn on 6 June 1944, 225 US Army Rangers under Lt. Col. James Rudder landed beneath the sheer 100-foot cliffs of Pointe du Hoc, between Omaha and Utah, to destroy a battery of six 155mm guns that threatened both beaches. Firing rocket-propelled grappling hooks and climbing rope ladders under German fire, they scaled the cliff—only to find the guns had been moved inland. A patrol located and destroyed them in an orchard. The Rangers then held the position against fierce counterattacks for two days; of 225 men, only about 90 remained fit to fight. The cratered clifftop, still pitted by bombardment, is preserved as an American memorial.",
    fullDescriptionZh: "1944年6月6日拂晓，225名美军突击队员在鲁德中校率领下，在奥马哈与犹他之间陡峭的百英尺奥克角悬崖下登陆，任务是摧毁威胁两个海滩的六门155毫米火炮。他们在德军火力下发射火箭抓钩、攀爬绳梯登上悬崖——却发现火炮已被移至内陆。一支巡逻队在果园中找到并炸毁了它们。突击队随后顶住猛烈反击坚守阵地两天；225人中只剩约90人尚能作战。弹坑遍布的崖顶至今仍留有轰炸痕迹，作为美国纪念地保留。",
