    fullDescription: "Gold Beach, the central of the five landing sectors, was assaulted on 6 June 1944 by the British 50th (Northumbrian) Infantry Division. Specialised armour—Hobart's 'Funnies', including flail tanks that cleared mines—helped troops break through the seawall and coastal villages such as Le Hamel and Asnelles. By day's end the British had pushed six miles inland, nearly reaching Bayeux, and linked toward the Canadians on Juno. Here Company Sergeant Major Stanley Hollis performed the only actions of D-Day to earn the Victoria Cross. Just offshore at Arromanches, engineers would soon assemble the giant Mulberry 'B' artificial harbour to supply the invasion.",
    fullDescriptionZh: "金色海滩是五个登陆区的中央，1944年6月6日由英军第50（诺森伯兰）步兵师突击。专用装甲——霍巴特的「滑稽玩意」，包括清雷的连枷坦克——帮助部队突破海堤和勒阿梅尔、阿涅勒等沿海村庄。到日终，英军向内陆推进六英里，几乎抵达巴约，并向朱诺海滩的加拿大军靠拢。连队军士长斯坦利·霍利斯在此完成了D日唯一荣获维多利亚十字勋章的英勇行动。就在附近的阿罗芒什海外，工兵不久将组装巨大的桑葚「B」人工港以补给登陆。",
