    fullDescription: "Juno Beach was assaulted on 6 June 1944 by the 3rd Canadian Infantry Division, tasked with taking Courseulles, Bernières and Saint-Aubin. The first waves hit the beach late, at high tide, forcing landing craft onto mined obstacles under heavy fire; casualties in the opening minutes were severe, with some companies losing half their men. Yet the Canadians fought through the seaside towns and by nightfall had advanced further inland than any other Allied force on D-Day, nearing the Caen–Bayeux road. Of roughly 14,000 Canadians who landed, some 340 were killed that day. The Juno Beach Centre now commemorates Canada's wartime effort.",
