    region: "France",
    year: "1944",
    coordinates: { lat: 49.2950, lng: -0.2700 },
    description: "The easternmost D-Day beach, where a French commando piper played his men ashore.",
    descriptionZh: "最东端的D日海滩，一名法国突击队风笛手吹奏着送战友上岸。",
    fullDescription: "Sword, the easternmost D-Day beach, was assaulted on 6 June 1944 by the British 3rd Infantry Division with Lord Lovat's 1st Special Service Brigade—including 177 Free French commandos of Commander Philippe Kieffer, the only Frenchmen to land on D-Day. As the men waded ashore, Lovat's personal piper Bill Millin defiantly played the bagpipes under fire. The commandos pushed inland to relieve the airborne troops holding Pegasus Bridge. Sword's advance toward Caen was slowed by German armour, and the city would not fall for weeks. The beach today fronts the resort town of Ouistreham, its bunkers preserved as museums.",
    fullDescriptionZh: "宝剑是最东端的D日海滩，1944年6月6日由英军第3步兵师与洛瓦特勋爵的第1特勤旅突击——其中包括基弗指挥官的177名自由法国突击队员，他们是D日唯一登陆的法国人。士兵涉水上岸时，洛瓦特的私人风笛手比尔·米林在火力下傲然吹奏风笛。突击队向内陆挺进，去解救坚守佩加索斯桥的空降部队。宝剑海滩向卡昂的推进被德军装甲拖慢，该城数周后才陷落。如今海滩前方是度假小镇乌伊斯特雷昂，碉堡被保留为博物馆。",
