    region: "France",
    year: "1944",
    coordinates: { lat: 49.4089, lng: -1.3167 },
    description: "The first French town liberated, where a paratrooper dangled from the church steeple all night.",
    descriptionZh: "首个获得解放的法国小镇，一名伞兵整夜悬挂在教堂尖塔上。",
    fullDescription: "In the pre-dawn hours of 6 June 1944, American paratroopers of the 82nd and 101st Airborne dropped around Sainte-Mère-Église to seize road junctions behind Utah Beach. Some men fell straight into the town square, lit by a burning building, and were shot as they descended. Private John Steele's parachute snagged on the church steeple, leaving him hanging helplessly for hours, feigning death while the battle raged below—an episode immortalised in the film The Longest Day. By morning the town was in American hands, the first in France to be liberated. A dummy paratrooper still hangs from the church tower in tribute.",
    fullDescriptionZh: "1944年6月6日拂晓前，美军第82和第101空降师的伞兵在圣梅尔埃格利斯周围空降，以夺取犹他海滩后方的道路交叉口。有些人直接落入被燃烧建筑照亮的镇广场，在降落时被击中。列兵约翰·斯蒂尔的降落伞挂在教堂尖塔上，让他无助地悬挂数小时，在下方激战时装死——这一幕在电影《最长的一天》中永载史册。到清晨小镇落入美军之手，成为法国首个获得解放的城镇。一具假伞兵至今仍悬挂在教堂塔楼上以示纪念。",
