    nameZh: "佩加索斯桥",
    type: "historical",
    region: "France",
    year: "1944",
    coordinates: { lat: 49.2422, lng: -0.2744 },
    description: "The canal bridge seized in a daring midnight glider raid, the first Allied action of D-Day.",
    descriptionZh: "午夜滑翔机突袭夺取的运河桥，D日盟军的第一场行动。",
    fullDescription: "Just after midnight on 6 June 1944, six Horsa gliders carrying men of the British 6th Airborne, led by Major John Howard, crash-landed within yards of the bridge over the Caen Canal at Bénouville. In a ten-minute assault they seized the bridge intact, denying it to German reinforcements—the first Allied action of D-Day. Lieutenant Den Brotheridge, shot in the attack, became the first Allied soldier killed by enemy fire on 6 June. The bridge, later nicknamed Pegasus after the airborne emblem, was held until relieved by Lovat's commandos from Sword Beach. The original bridge now stands in a nearby memorial museum.",
    fullDescriptionZh: "1944年6月6日午夜刚过，载着英军第6空降师、由约翰·霍华德少校率领的六架霍萨滑翔机，在贝努维尔卡昂运河桥数码之内迫降。在十分钟的突击中他们完好夺下大桥，不让德军增援使用——这是D日盟军的第一场行动。在攻击中中弹的登·布拉泽里奇中尉成为6月6日首个被敌火击毙的盟军士兵。这座后来以空降部队徽章命名为「佩加索斯」的桥，坚守到来自宝剑海滩的洛瓦特突击队增援。原桥如今陈列在附近的纪念博物馆内。",
