    year: "1944",
    coordinates: { lat: 49.3574, lng: -0.8558 },
    description: "9,388 white crosses on the bluff above Omaha Beach, overlooking the sands they died to take.",
    descriptionZh: "奥马哈海滩上方峭壁上的9388座白色十字架，俯瞰着他们为夺取而牺牲的沙滩。",
    fullDescription: "On the bluff overlooking Omaha Beach, the Normandy American Cemetery holds the graves of 9,388 US service members, most killed during the D-Day landings and the ensuing Battle of Normandy in 1944. Rows of white marble crosses and Stars of David stretch across 172 immaculate acres of ground granted in perpetuity to the United States by France. A memorial colonnade, reflecting pool and the bronze statue 'Spirit of American Youth' anchor the site, while a Wall of the Missing lists 1,557 names. Among the graves lie the two Niland brothers whose story inspired Saving Private Ryan. Over a million people visit each year.",
    fullDescriptionZh: "在俯瞰奥马哈海滩的峭壁上，诺曼底美军公墓安葬着9388名美军官兵，多数在1944年D日登陆及随后的诺曼底战役中牺牲。一排排白色大理石十字架和大卫星，铺展在法国永久授予美国的172英亩洁净土地上。纪念柱廊、倒影池和青铜雕像「美国青年之魂」为墓地核心，失踪者之墙列有1557个名字。墓中长眠着尼兰兄弟中的两人，他们的故事启发了《拯救大兵瑞恩》。每年逾百万人到访。",
