    description: "The spa town whose name became a byword for collaboration with Nazi Germany.",
    descriptionZh: "这座温泉小镇的名字成了与纳粹德国合作的代名词。",
    fullDescription: "After France's defeat in June 1940, the collaborationist government of Marshal Philippe Pétain established its capital in the spa town of Vichy, chosen for its many hotels to house ministries in the unoccupied southern zone. On 10 July 1940 the National Assembly, meeting in Vichy's Grand Casino, voted to grant Pétain full powers, effectively ending the Third Republic. The 'État Français' pursued a policy of collaboration, passed antisemitic laws, and deported some 75,000 Jews. Germany occupied the southern zone too in November 1942, hollowing out Vichy's authority. Liberated in 1944, the elegant town has struggled ever since with the dark weight its very name now carries.",
    fullDescriptionZh: "1940年6月法国战败后，贝当元帅的通敌政府将首都设在温泉小镇维希，因其众多旅馆可在未被占领的南部区容纳各部委。1940年7月10日，国民议会在维希大赌场开会，投票授予贝当全权，实际上终结了第三共和国。「法兰西国」推行合作政策，颁布反犹法律，驱逐了约7.5万名犹太人。1942年11月德国也占领了南部区，架空了维希的权威。1944年获得解放后，这座优雅的小镇始终背负着如今其名字所承载的黑暗重量。",
