    id: 11031,
    name: "Dunkirk (Dunkerque)",
    nameZh: "敦刻尔克",
    type: "historical",
    region: "France",
    year: "1940",
    coordinates: { lat: 51.0344, lng: 2.3768 },
    description: "The beaches from which 338,000 trapped Allied troops were evacuated by a fleet of little ships.",
    descriptionZh: "33.8万名被困盟军士兵从这些海滩上被一支小船船队撤离。",
    fullDescription: "In late May 1940, the German blitzkrieg trapped the British Expeditionary Force and French troops against the sea at Dunkirk. Between 26 May and 4 June, Operation Dynamo evacuated some 338,000 Allied soldiers across the Channel—rescued not only by warships but by an armada of civilian 'little ships', yachts, fishing boats and pleasure craft that ferried men from the shallow beaches. Under constant Luftwaffe attack, and screened by a doomed French rearguard, the withdrawal saved the core of Britain's army. Churchill called it 'a miracle of deliverance' while warning that 'wars are not won by evacuations'. The beaches and the 1940 memorials draw visitors and film-makers alike.",
    fullDescriptionZh: "1940年5月下旬，德军闪电战把英国远征军和法军困在敦刻尔克海边。5月26日至6月4日，「发电机行动」将约33.8万名盟军士兵撤过英吉利海峡——不仅靠军舰，还靠一支平民「小船」船队，游艇、渔船和游乐艇从浅滩接运士兵。在德国空军不断轰炸下，靠注定牺牲的法军后卫掩护，这次撤退保住了英国军队的核心。丘吉尔称之为「拯救的奇迹」，同时警告「战争不是靠撤退赢得的」。海滩和1940年纪念馆吸引着游客与电影人。",
