    description: "The coronation church of French kings, where Joan of Arc saw her dauphin crowned in 1429.",
    descriptionZh: "法国国王的加冕教堂，1429年贞德在此见证她的王太子加冕。",
    fullDescription: "Begun in 1211, the Gothic cathedral of Notre-Dame de Reims became the traditional site of French royal coronations, a role rooted in the baptism of Clovis, king of the Franks, in Reims around 496. Thirty-three kings were crowned beneath its soaring nave. Its most fabled moment came on 17 July 1429, when Joan of Arc, having lifted the siege of Orléans, stood beside Charles VII as he was consecrated king, fulfilling her divine mission. In September 1914 German shelling set the cathedral's timbers ablaze, gutting it; its post-war restoration, aided by Rockefeller funds, and its luminous Chagall windows now crown a masterpiece reborn.",
    fullDescriptionZh: "始建于1211年的兰斯圣母哥特式大教堂，成为法国王室加冕的传统场所，这一传统可追溯到约496年法兰克国王克洛维在兰斯受洗。三十三位国王在其高耸的中殿下加冕。它最传奇的时刻是1429年7月17日，贞德解除奥尔良之围后，站在查理七世身旁见证他被祝圣为王，完成她的神圣使命。1914年9月德军炮击点燃教堂木构，将其烧毁；战后在洛克菲勒基金资助下修复，加上夏加尔绚丽的彩窗，如今为这座重生的杰作加冕。",
