    year: "1431",
    coordinates: { lat: 49.4432, lng: 1.0888 },
    description: "The market square where the 19-year-old Maid of Orléans was burned at the stake.",
    descriptionZh: "19岁的奥尔良少女被绑上火刑柱焚烧的集市广场。",
    fullDescription: "On 30 May 1431, in the Old Market Square of English-held Rouen, the 19-year-old Joan of Arc was burned at the stake as a heretic after a rigged ecclesiastical trial. The peasant girl who had rallied France and seen Charles VII crowned had been captured, sold to the English, and condemned by a court of pro-English clergy. Witnesses said her executioner feared he had 'burned a saint'; her ashes were cast into the Seine. Twenty-five years later a retrial annulled the verdict, and in 1920 she was canonised. A soaring modern church, its roof evoking flames, now marks the spot, beside a cross where she died.",
    fullDescriptionZh: "1431年5月30日，在英军占领的鲁昂旧集市广场，19岁的贞德经过操纵的教会审判后，作为异端被绑上火刑柱焚烧。这个曾唤起法国、见证查理七世加冕的农家少女，被俘后卖给英国人，由亲英教士组成的法庭定罪。目击者说她的刽子手担心自己「烧死了一位圣人」；她的骨灰被撒入塞纳河。二十五年后重审推翻了判决，1920年她被封圣。如今一座造型高耸、屋顶似火焰的现代教堂标记着这一地点，旁边立着她殉难处的十字架。",
    historicalImage: "/images/locations/historical/rouen-joan-of-arcs-execution-site-historical.jpg",
