    description: "The besieged city whose relief by Joan of Arc turned the tide of the Hundred Years' War.",
    descriptionZh: "被围困的城市，贞德解围扭转了百年战争的战局。",
    fullDescription: "By 1428 the English had besieged Orléans, the last major stronghold barring their advance to the south of France in the Hundred Years' War. In April 1429 a teenage peasant girl, Joan of Arc, arrived claiming divine command to save France. Inspiring the demoralised garrison, she led aggressive assaults and, on 8 May 1429, the English abandoned the siege after just nine days of her presence—a turning point that revived French fortunes and led directly to the coronation of Charles VII. Ever since, Orléans has honoured 'the Maid' each 8 May with the Fêtes de Jeanne d'Arc, among Europe's oldest continuous civic festivals, held for nearly six centuries.",
    fullDescriptionZh: "到1428年，英军已围困奥尔良，这是百年战争中阻挡他们南下法国的最后一座主要要塞。1429年4月，一个少女农家女贞德抵达，宣称受神命拯救法国。她鼓舞士气低落的守军，率领猛烈进攻，1429年5月8日，在她到来仅九天后英军放弃围城——这一转折点复兴了法国国运，直接促成查理七世加冕。此后，奥尔良每年5月8日以「贞德节」纪念这位「少女」，这是欧洲最古老的连续市民节庆之一，已举办近六个世纪。",
