    descriptionZh: "双重城墙的中世纪堡垒城市，在血腥的阿尔比十字军东征中被攻陷。",
    fullDescription: "Ringed by nearly 3 kilometres of double walls and 52 towers, the Cité de Carcassonne is Europe's largest surviving medieval fortified town, its foundations Roman and its ramparts Visigothic and later. In 1209 it was besieged and captured during the Albigensian Crusade, the papal war against the Cathar heretics of southern France; its viscount, Raymond-Roger Trencavel, was imprisoned and died in its dungeon. Absorbed by the French crown, it guarded the frontier with Aragon until the border shifted in 1659, leaving it to decay. Slated for demolition in the 19th century, it was dramatically restored by architect Viollet-le-Duc from 1853, whose pointed turrets give it its fairy-tale silhouette.",
    fullDescriptionZh: "环以近3公里双重城墙和52座塔楼，卡尔卡松城是欧洲现存最大的中世纪设防城镇，其地基为罗马时期，城墙为西哥特及后世所建。1209年，在教皇对法国南部卡特里派异端发动的阿尔比十字军东征中，它被围攻并陷落；子爵雷蒙-罗歇·特朗卡韦尔被囚，死于地牢。并入法国王室后，它守卫着与阿拉贡的边境，直到1659年边界改变后任其衰败。19世纪本定拆除，1853年起由建筑师维奥莱-勒-杜克戏剧性地修复，他尖顶的塔楼赋予它童话般的轮廓。",
