    fullDescription: "In 1309, amid turmoil in Italy, Pope Clement V moved the papacy from Rome to Avignon, beginning an era later dubbed the 'Babylonian Captivity' of the Church. For nearly 70 years, seven French popes ruled from here, raising the Palais des Papes—the largest Gothic palace in Europe, a fortress of towering stone walls enclosing lavish frescoed chambers. The court became a byword for wealth and, critics charged, corruption. The papacy returned to Rome in 1377, but a rival line of antipopes clung to Avignon during the Great Western Schism until 1403. The nearby Pont d'Avignon, immortalised in song, once spanned the Rhône.",
    fullDescriptionZh: "1309年，意大利动荡之际，教皇克莱门特五世将教廷从罗马迁至阿维尼翁，开启了后来被称为教会「巴比伦之囚」的时代。近70年间，七位法国教皇从此统治，建起了教皇宫——欧洲最大的哥特式宫殿，高耸石墙的堡垒环绕着华丽的壁画厅堂。这座宫廷成为财富的代名词，也被批评者指为腐败。教廷1377年返回罗马，但大分裂期间一支敌对的对立教皇一直盘踞阿维尼翁至1403年。附近因歌谣而不朽的阿维尼翁桥曾横跨罗讷河。",
