    fullDescription: "Built by Roman engineers around the middle of the first century AD, the Pont du Gard carried the aqueduct of Nîmes across the Gardon river gorge, part of a 50-kilometre channel that supplied the Roman city with an estimated 40,000 cubic metres of water a day. Rising 49 metres in three tiers of arches, it is the tallest surviving Roman aqueduct bridge, its precisely cut limestone blocks—some weighing six tonnes—assembled without mortar. The channel's gradient drops only about 34 centimetres over its final kilometres, a marvel of ancient surveying. Abandoned after Rome's fall, it survived partly because it doubled as a toll road bridge through the Middle Ages.",
    fullDescriptionZh: "加尔桥由罗马工程师约建于公元一世纪中叶，将尼姆引水渠跨越加尔东河峡谷，是一条50公里水道的一部分，据估计每天为这座罗马城市供水4万立方米。它以三层拱券高耸49米，是现存最高的罗马引水渠桥，精确切割的石灰岩块——有的重达六吨——不用灰浆拼接。水道在最后数公里的坡降仅约34厘米，是古代测量的奇迹。罗马陷落后被弃用，它部分因中世纪兼作收费公路桥而幸存。",
