    fullDescription: "In 52 BC the Gallic chieftain Vercingetorix, having united the tribes in revolt, made his final stand against Julius Caesar at the hilltop oppidum of Alesia. Caesar besieged the fortress with an astonishing double ring of siege works—an inner wall to trap Vercingetorix and an outer one to fend off a vast Gallic relief army of perhaps a quarter-million men. When the relief attacks failed, the starving Vercingetorix surrendered, riding out to lay his arms at Caesar's feet. He was paraded in Caesar's triumph in Rome and executed years later. Alesia sealed the conquest of Gaul; the site near Alise-Sainte-Reine now holds a museum and a 19th-century statue of the vanquished hero.",
    fullDescriptionZh: "公元前52年，高卢首领维钦托利联合各部族起义后，在山顶要塞阿莱西亚向尤利乌斯·凯撒做最后抵抗。凯撒以惊人的双重围城工事围困要塞——内墙困住维钦托利，外墙抵御一支或许多达二十五万人的庞大高卢援军。援军进攻失败后，饥饿的维钦托利投降，骑马出城将武器置于凯撒脚下。他在凯撒的罗马凯旋式中被游街，数年后被处决。阿莱西亚奠定了对高卢的征服；阿利兹-圣雷讷附近的遗址如今有一座博物馆和一尊19世纪这位战败英雄的雕像。",
