    fullDescription: "Built in the early first century AD under Augustus, the Roman theatre of Orange is one of the best-preserved in the world, above all for its immense stage wall—the frons scaenae—103 metres wide and 37 metres high, still bearing a 3.5-metre statue of the emperor. Louis XIV reputedly called it 'the finest wall in my kingdom'. Seating around 9,000 spectators, it staged plays and imperial spectacles. Closed by the Church in 391 AD as pagan and later used as a defensive refuge, it was restored in the 19th century and now hosts the acclaimed Chorégies d'Orange opera festival each summer, its ancient acoustics still carrying a singer's voice to the topmost tier.",
