    fullDescription: "Chenonceau arches gracefully across the River Cher on a series of stone bridges, earning it the name 'Château des Dames' for the women who shaped it. Henry II gave it to his mistress Diane de Poitiers, who built the bridge over the river. When the king died in 1559, his widow Catherine de' Medici forced Diane out and added the gallery atop the bridge, hosting extravagant fêtes. In the First World War the gallery served as a military hospital; in the Second, the river beneath the château marked the boundary between occupied and free France, and the building became a secret crossing point for the Resistance and refugees fleeing the Nazis.",
    fullDescriptionZh: "舍农索城堡以一系列石桥优雅地横跨谢尔河，因塑造它的女性而得名「贵妇城堡」。亨利二世将它赐给情妇黛安·德·普瓦捷，她建起了跨河的桥。1559年国王去世后，遗孀凯瑟琳·德·美第奇逼走黛安，在桥上加建长廊，举办奢华宴会。第一次世界大战中，长廊充当军事医院；第二次世界大战中，城堡下方的河流标记着被占领法国与自由法国的分界，建筑成为抵抗运动和逃避纳粹难民的秘密越境点。",
