    fullDescription: "In 1516, at the invitation of the young King Francis I, the ageing Leonardo da Vinci crossed the Alps to France, bringing three paintings including the Mona Lisa, and settled at the manor of Clos Lucé beside the royal château of Amboise. Named the king's 'first painter, engineer and architect', he spent his final years sketching inventions, designing court festivities and a never-built palace, though a stroke had partly paralysed his hand. He died at Clos Lucé on 2 May 1519; legend, popularised by a painting, holds that he expired in the arms of Francis I. Today the manor displays models of his machines built from his notebooks.",
    fullDescriptionZh: "1516年，应年轻国王弗朗索瓦一世之邀，年迈的达·芬奇翻越阿尔卑斯山来到法国，带来包括《蒙娜丽莎》在内的三幅画作，定居于王家昂布瓦斯城堡旁的克洛·吕塞庄园。被封为国王的「首席画家、工程师与建筑师」，他在生命最后几年绘制发明、设计宫廷庆典和一座从未建成的宫殿，尽管中风已使他的手部分瘫痪。他于1519年5月2日在克洛·吕塞去世；经一幅画作传播的传说称，他在弗朗索瓦一世怀中辞世。如今庄园根据他的笔记本展示其机械模型。",
