    fullDescription: "Perched above the Loire, the royal Château of Amboise was a favoured residence of French kings and the childhood home of Francis I. Leonardo da Vinci, who died nearby in 1519, is believed to be buried in the château's chapel of Saint-Hubert. In March 1560 the castle was the scene of the Amboise Conspiracy, a botched Protestant plot to seize the young king Francis II from the Catholic Guise family; its brutal suppression saw hundreds of Huguenots executed, some hanged from the château's balconies and battlements—an early spasm of the French Wars of Religion. The Renaissance castle, though much reduced since, still commands the river valley.",
    fullDescriptionZh: "昂布瓦斯王家城堡高踞卢瓦尔河上，是法国国王钟爱的居所，也是弗朗索瓦一世的童年之家。1519年在附近去世的达·芬奇，据信安葬于城堡的圣于贝尔礼拜堂。1560年3月，城堡成为昂布瓦斯阴谋的现场，这是一场失败的新教密谋，企图从天主教吉斯家族手中夺取年轻的国王弗朗索瓦二世；其残酷镇压导致数百名胡格诺派被处决，一些人被绞死在城堡的阳台和城垛上——这是法国宗教战争的早期抽搐。这座文艺复兴城堡虽已大为缩减，仍俯瞰着河谷。",
