    description: "The château where Henry III had the mighty Duke of Guise murdered before his own eyes.",
    descriptionZh: "亨利三世在此当着自己的面下令刺杀权势熏天的吉斯公爵的城堡。",
    fullDescription: "The royal Château de Blois, home to seven kings and ten queens, is a stone chronicle of French architecture, its wings ranging from Gothic to Renaissance to Classical, including Francis I's celebrated spiral staircase. Its darkest drama unfolded on 23 December 1588, when King Henry III, threatened by the over-mighty Duke Henry of Guise, leader of the Catholic League, summoned him to the royal apartments and had his guards stab the duke to death; his brother the Cardinal was killed the next day. Within months Henry III himself was assassinated, ending the House of Valois. Later Marie de' Medici was imprisoned at Blois and made a dramatic escape down a rope ladder.",
    fullDescriptionZh: "布卢瓦王家城堡是七位国王和十位王后的居所，是法国建筑的石质编年史，其翼楼横跨哥特、文艺复兴到古典风格，包括弗朗索瓦一世著名的螺旋楼梯。其最黑暗的一幕发生在1588年12月23日，国王亨利三世受到权势过盛的天主教联盟领袖吉斯公爵亨利威胁，将他召入王家寝宫，命卫兵将公爵刺死；其弟枢机次日也被杀。数月内亨利三世本人遇刺，瓦卢瓦王朝就此终结。后来玛丽·德·美第奇被囚于布卢瓦，曾戏剧性地顺绳梯逃脱。",
