    name: "Forteresse Royale de Chinon",
    nameZh: "希农王家城堡",
    type: "heritage",
    region: "France",
    year: "1429",
    coordinates: { lat: 47.1683, lng: 0.2358 },
    description: "The clifftop fortress where Joan of Arc first met the dauphin—and picked him from a crowd.",
    descriptionZh: "崖顶要塞，贞德在此初见王太子——并从人群中认出了他。",
    fullDescription: "The great fortress of Chinon, strung along a ridge above the Vienne river, was a stronghold of the Plantagenets—Henry II of England died here in 1189—and later a refuge of the French crown. Its most famous moment came in March 1429, when the peasant girl Joan of Arc arrived seeking the disinherited dauphin Charles. According to tradition, Charles hid among his courtiers to test her, but Joan picked him unerringly from the crowd and told him she had come, sent by God, to see him crowned king of France. Convinced, he gave her an army; the road to Orléans and Reims began at Chinon. The fortress has been extensively restored.",
    fullDescriptionZh: "希农大要塞沿维埃纳河上方的山脊延展，曾是金雀花王朝的堡垒——英格兰的亨利二世1189年死于此地——后来成为法国王室的避难所。它最著名的时刻是1429年3月，农家少女贞德前来寻找被剥夺继承权的王太子查理。相传查理藏身于廷臣之中以试探她，但贞德毫不犹豫地从人群中认出他，告诉他自己奉神差遣前来，要见他加冕为法国国王。查理深信不疑，给了她一支军队；通往奥尔良和兰斯的道路始于希农。这座要塞已经过大规模修复。",
    historicalImage: "/images/locations/historical/forteresse-royale-de-chinon-historical.jpg",
