    year: "1524",
    coordinates: { lat: 43.2797, lng: 5.3253 },
    description: "The island prison-fortress immortalised as the dungeon of the Count of Monte Cristo.",
    descriptionZh: "被永载为《基督山伯爵》地牢的岛屿监狱堡垒。",
    fullDescription: "Built on a tiny island off Marseille in 1524 on the orders of Francis I to defend the coast, the Château d'If soon became a notorious state prison. Its isolation made escape seem impossible, and it held Protestants, political prisoners and revolutionaries in grim cells for centuries. Yet its true fame is fictional: Alexandre Dumas set the harrowing imprisonment of Edmond Dantès here in The Count of Monte Cristo (1844), and visitors still ask to see the (invented) cells of Dantès and the Abbé Faria. Decommissioned as a prison and opened to the public in 1890, the fortress broods on its rock, ringed by the Mediterranean, exactly as Dumas's readers imagine it.",
    fullDescriptionZh: "伊夫堡1524年奉弗朗索瓦一世之命建于马赛外一座小岛上以防卫海岸，不久便成为臭名昭著的国家监狱。其与世隔绝使逃脱看似不可能，数百年间它在阴森的牢房中关押新教徒、政治犯和革命者。然而其真正的声名源于虚构：大仲马在《基督山伯爵》（1844年）中将埃德蒙·唐泰斯惨痛的囚禁设于此地，游客至今仍要求参观唐泰斯和法里亚神甫（虚构的）牢房。1890年退役并向公众开放后，这座要塞盘踞在岩石上、被地中海环绕，正如大仲马的读者所想象。",
