    descriptionZh: "曾数百年为世界最高建筑，坐落在75年间四度易主的城市。",
    fullDescription: "Completed in 1439, the pink-sandstone Cathedral of Strasbourg soared to 142 metres and remained the tallest building in the world until 1874—an astonishing 435 years. Victor Hugo called it 'a gigantic and delicate marvel'. It stands in a city that has embodied the tug-of-war between France and Germany: Strasbourg was seized by Louis XIV in 1681, annexed by the German Empire in 1871, returned to France in 1918, reannexed by Nazi Germany in 1940, and freed in 1944. That turbulent frontier history is why Strasbourg now hosts the European Parliament as a symbol of Franco-German reconciliation. The cathedral's astronomical clock still performs its noon parade of apostles.",
    fullDescriptionZh: "斯特拉斯堡粉红砂岩大教堂1439年竣工，高耸142米，直到1874年一直是世界最高建筑——惊人的435年。雨果称它为「巨大而精致的奇迹」。它所在的城市体现了法德之间的拉锯：斯特拉斯堡1681年被路易十四夺取，1871年被德意志帝国吞并，1918年归还法国，1940年被纳粹德国重新吞并，1944年获得解放。这段动荡的边境历史正是斯特拉斯堡如今作为法德和解象征而设有欧洲议会的原因。大教堂的天文钟至今仍在正午上演使徒游行。",
