    id: 11056,
    name: "Petite France, Strasbourg",
    nameZh: "小法兰西（斯特拉斯堡）",
    type: "heritage",
    region: "France",
    year: "1500",
    coordinates: { lat: 48.5804, lng: 7.7395 },
    description: "The half-timbered canal quarter of tanners, in the Alsatian city torn between two nations.",
    descriptionZh: "鞣皮匠的半木结构运河街区，坐落在夹在两国之间的阿尔萨斯城市。",
    fullDescription: "The picturesque Petite France district grew up in the 16th century as the quarter of Strasbourg's tanners, millers and fishermen, its steep-roofed, half-timbered houses lining canals where hides were once washed and dried in open lofts. Its curious name derives from a hospital for sufferers of the 'French disease' (syphilis) founded here around 1500. As Strasbourg passed repeatedly between French and German rule, the district preserved the distinctly Alsatian architecture that blends both cultures. Spared major war damage, its covered bridges (Ponts Couverts) and lock-lined waterways now form part of the UNESCO-listed Grande Île, one of France's most photographed historic townscapes.",
    fullDescriptionZh: "如画的小法兰西区在16世纪作为斯特拉斯堡鞣皮匠、磨坊主和渔民的街区兴起，陡峭屋顶的半木结构房屋沿运河排列，兽皮曾在敞开的阁楼中冲洗晾晒。其奇特的名字源于约1500年在此创建的一所收治「法国病」（梅毒）患者的医院。随着斯特拉斯堡在法德统治间反复易手，这个街区保留了融合两种文化、独具阿尔萨斯特色的建筑。它免于重大战争破坏，其加盖桥（廊桥）和船闸密布的水道如今是列入联合国名录的大岛的一部分，是法国被拍摄最多的历史城镇景观之一。",
    historicalImage: "/images/locations/historical/petite-france-strasbourg-historical.jpg",
    modernImage: "/images/locations/petite-france-strasbourg.jpg",
