    descriptionZh: "拥有15扇高耸彩窗的珠宝盒，为安放基督荆棘冠而建。",
    fullDescription: "King Louis IX—Saint Louis—built the Sainte-Chapelle in barely seven years, consecrating it in 1248, as a colossal reliquary for the Crown of Thorns and other relics of Christ's Passion, which he had purchased from the Latin Emperor of Constantinople for a sum greater than the chapel itself cost. Its upper chapel is a cage of stained glass: fifteen windows soaring 15 metres tell over a thousand biblical scenes, flooding the space with jewel-like light so that the stone almost disappears. Damaged in the Revolution and restored in the 19th century, roughly two-thirds of the glass is original 13th-century work—among the finest surviving anywhere in the world.",
    fullDescriptionZh: "国王路易九世——圣路易——仅用约七年就建成圣礼拜堂，1248年祝圣，作为安放荆棘冠及其他基督受难圣物的宏大圣物匣，这些圣物是他从君士坦丁堡的拉丁皇帝手中购得，价钱比礼拜堂本身还高。其上层礼拜堂是一座彩色玻璃的笼子：十五扇高耸15米的窗户讲述逾千个圣经场景，宝石般的光芒充盈空间，石材几乎消失不见。大革命中受损，19世纪修复，约三分之二的玻璃是13世纪的原作——是世界各地现存最精美的之一。",
