    coordinates: { lat: 48.8720, lng: 2.3316 },
    description: "The opulent opera house with a real underground lake that inspired The Phantom of the Opera.",
    descriptionZh: "拥有真实地下湖的华丽歌剧院，启发了《歌剧魅影》。",
    fullDescription: "Commissioned by Napoleon III and opened in 1875, the Palais Garnier is the flamboyant masterpiece of architect Charles Garnier, a riot of marble, gilt and a grand staircase built for the theatre of high society itself. Beneath the building lies a genuine subterranean water reservoir—engineers could not drain the site's groundwater, so they contained it—which, together with a real 1896 accident when a counterweight of the great chandelier fell and killed a spectator, inspired Gaston Leroux's 1910 novel The Phantom of the Opera. Marc Chagall painted its ceiling in 1964. Even after the Bastille opera opened in 1989, the Garnier remains Paris's temple of ballet and spectacle.",
    fullDescriptionZh: "加尼叶歌剧院由拿破仑三世下令建造，1875年开幕，是建筑师夏尔·加尼叶绚烂的杰作，大理石、镀金与宏伟楼梯的狂欢，为上流社会这出戏本身而建。建筑下方是一座真正的地下蓄水池——工程师无法排干场地的地下水，于是将其围蓄——这与1896年一次真实事故（大吊灯的配重坠落砸死一名观众）一起，启发了勒鲁1910年的小说《歌剧魅影》。夏加尔1964年绘制了它的天顶画。即便1989年巴士底歌剧院开幕后，加尼叶仍是巴黎芭蕾与盛景的殿堂。",
