    year: "1804",
    coordinates: { lat: 48.8614, lng: 2.3945 },
    description: "Paris's city of the dead, where the last Communards were shot against its wall in 1871.",
    descriptionZh: "巴黎的亡者之城，1871年最后的公社社员在其墙前被枪决。",
    fullDescription: "Opened in 1804 on a hillside once owned by Louis XIV's confessor, Père Lachaise became the world's most famous cemetery, its 44 hectares crowded with the tombs of Chopin, Balzac, Molière, Oscar Wilde, Édith Piaf and Jim Morrison. To attract burials, the city cannily transferred the supposed remains of Molière and Abélard and Héloïse here. Its most haunting corner is the Mur des Fédérés, where on 28 May 1871 the last 147 fighters of the Paris Commune were lined up and shot after a running gun-battle among the graves, their bodies flung into a trench—a site that became a rallying point for the French left. Wilde's tomb is still kissed by admirers.",
    fullDescriptionZh: "拉雪兹神父公墓1804年在一处曾属路易十四忏悔神父的山坡上开放，成为世界上最著名的公墓，其44公顷内密布肖邦、巴尔扎克、莫里哀、奥斯卡·王尔德、皮雅芙和吉姆·莫里森的墓。为吸引安葬，市政当局巧妙地将莫里哀及阿伯拉尔与埃洛伊丝的所谓遗骸迁至此地。其最令人难忘的角落是「联邦社员墙」，1871年5月28日，巴黎公社最后147名战士在墓地间的枪战后被排成一列枪决，尸体被抛入沟中——这一地点成为法国左翼的集结点。王尔德的墓至今仍被崇拜者亲吻。",
