    coordinates: { lat: 48.8425, lng: 2.4356 },
    description: "The tallest medieval keep in Europe, a royal fortress, prison, and site of a wartime massacre.",
    descriptionZh: "欧洲最高的中世纪主楼，皇家要塞、监狱，也是战时屠杀之地。",
    fullDescription: "The medieval Château de Vincennes, its 52-metre donjon the tallest fortified keep in Europe, grew from a royal hunting lodge into a formidable castle where kings were born and died—Henry V of England died here in 1422. Later it served as a state prison holding the philosopher Diderot, the future Mirabeau and the Marquis de Sade. In 1804 the Duke of Enghien was shot in its moat on Napoleon's orders, a killing that scandalised Europe. In August 1944, as they retreated, the Germans executed some 30 Resistance prisoners here and blew up part of the fortifications. Restored, the towering keep and its royal chapel now anchor a park on the edge of Paris.",
    fullDescriptionZh: "中世纪万塞讷城堡的52米主楼是欧洲最高的设防主楼，它从王家狩猎行宫成长为一座坚固的城堡，国王在此出生和去世——英格兰的亨利五世1422年死于此地。后来它充当国家监狱，关押过哲学家狄德罗、日后的米拉波和萨德侯爵。1804年，昂吉安公爵奉拿破仑之命在其护城河中被枪决，这一杀戮震惊欧洲。1944年8月撤退时，德军在此处决约30名抵抗运动囚犯并炸毁部分工事。修复后，高耸的主楼及其王家礼拜堂如今是巴黎边缘一座公园的核心。",
