    nameZh: "斯特鲁托夫——纳茨韦勒集中营",
    type: "historical",
    region: "France",
    year: "1941",
    coordinates: { lat: 48.4589, lng: 7.2531 },
    description: "The only Nazi concentration camp on French soil, hidden in the Vosges mountains.",
    descriptionZh: "唯一建在法国领土上的纳粹集中营，隐藏在孚日山脉中。",
    fullDescription: "In the annexed Alsatian mountains, the SS opened Natzweiler-Struthof in 1941—the only Nazi concentration camp established on French territory. Prisoners quarried pink granite and, from 1943, were subjected to pseudo-medical experiments; 86 Jews were murdered in a gas chamber built here so that their skeletons could form an anatomical 'collection' for a Nazi professor in Strasbourg. Members of the Resistance condemned under the 'Night and Fog' decree were sent here to vanish. Of some 52,000 deportees who passed through Struthof and its sub-camps, around 22,000 died. Evacuated in 1944 before the Allies arrived, the camp is now France's principal memorial to Nazi deportation.",
    fullDescriptionZh: "在被吞并的阿尔萨斯山区，党卫军1941年开设纳茨韦勒-斯特鲁托夫集中营——唯一建在法国领土上的纳粹集中营。囚犯开采粉红花岗岩，1943年起遭受伪医学实验；86名犹太人在此建的毒气室中被杀害，好让他们的骸骨为斯特拉斯堡一位纳粹教授组成解剖「藏品」。依「夜与雾」法令定罪的抵抗运动成员被送来此地消失。经斯特鲁托夫及其附属营的约5.2万名被驱逐者中，约2.2万人死亡。1944年盟军到来前撤空，这座集中营如今是法国纪念纳粹驱逐的主要场所。",
