    coordinates: { lat: 47.4661, lng: 3.7486 },
    description: "The Romanesque hilltop basilica from which the Second Crusade was preached in 1146.",
    descriptionZh: "1146年在此宣讲第二次十字军东征的罗曼式山顶大教堂。",
    fullDescription: "Rising on a Burgundian hill, the abbey church of Sainte-Marie-Madeleine at Vézelay drew medieval pilgrims by the thousand who believed it held the relics of Mary Magdalene, making it a major starting point of the pilgrimage to Santiago de Compostela. From the hill below, Saint Bernard of Clairvaux preached the Second Crusade before King Louis VII in 1146; in 1190 Richard the Lionheart and Philip Augustus set out on the Third Crusade from here. The basilica's carved tympanum and the celestial light of its nave are masterpieces of Romanesque art. Decayed and struck by lightning, it was rescued from ruin by the young Viollet-le-Duc in the 1840s.",
    fullDescriptionZh: "韦兹莱的圣抹大拉的马利亚修道院教堂矗立在勃艮第山丘上，吸引成千上万相信它藏有抹大拉的马利亚圣物的中世纪朝圣者，使它成为通往圣地亚哥-德孔波斯特拉朝圣之路的主要起点。1146年，克莱尔沃的圣伯尔纳铎在山下当着国王路易七世的面宣讲第二次十字军东征；1190年狮心王理查和腓力二世从此地出发参加第三次十字军东征。大教堂雕刻的门楣和中殿的天堂之光是罗曼式艺术的杰作。它曾衰败并遭雷击，1840年代被年轻的维奥莱-勒-杜克从废墟中拯救。",
