    descriptionZh: "曾是基督教世界最大的教堂、修道院帝国的心脏——如今仅存残片。",
    fullDescription: "Founded in 910, the Benedictine Abbey of Cluny became the most powerful monastery in medieval Europe, head of an order of over a thousand houses and virtually a state within the Church, answering only to the Pope. Its great abbey church, 'Cluny III', completed in the 12th century, was the largest church in Christendom—187 metres long—until the new St Peter's in Rome surpassed it centuries later. Cluny shaped Western monasticism, art and the Gregorian reform. But the Revolution suppressed the abbey, and from 1798 the colossal church was sold off and quarried for stone, leaving barely a tenth standing. The surviving south transept still hints at its vanished immensity.",
    fullDescriptionZh: "克吕尼本笃会修道院910年创建，成为中世纪欧洲最强大的修道院，一个逾千座修院教团的首领，实际上是教会内的一个国家，仅对教皇负责。其宏伟的修道院教堂「克吕尼三世」12世纪竣工，是基督教世界最大的教堂——长187米——直到数百年后罗马新的圣彼得大教堂才超越它。克吕尼塑造了西方修道制度、艺术和格里高利改革。但大革命废除了修道院，从1798年起，这座宏伟的教堂被变卖、当作采石场，仅存不到十分之一。幸存的南耳堂仍隐约透露其消失的宏大。",
