    descriptionZh: "哥特式建筑的发源地，几乎所有法国国王的陵寝。",
    fullDescription: "When Abbot Suger rebuilt the choir of Saint-Denis and dedicated it in 1144, flooding it with light through pointed arches and vast windows, he inadvertently launched the Gothic style that would sweep Europe. Just as significant is its role as the royal necropolis of France: from the early Middle Ages to 1789, nearly every French king was buried here, their tombs a gallery of recumbent effigies from Dagobert to Louis XVI. During the Revolution, in 1793, the mob desecrated the tombs, exhuming royal remains and flinging them into common pits. Restored in the 19th century, the basilica gathered the scattered effigies back—a stone parliament of the dead monarchy.",
    fullDescriptionZh: "当絮热院长重建圣但尼的唱诗席并于1144年将其奉献时，透过尖拱和巨大窗户让光线充盈其间，无意中开创了将席卷欧洲的哥特式风格。同样重要的是它作为法国王室陵寝的角色：从中世纪早期到1789年，几乎每位法国国王都葬于此，他们的墓构成一座从达戈贝尔到路易十六的卧像长廊。大革命期间的1793年，民众亵渎了这些墓，掘出王室遗骸并抛入公共坑穴。19世纪修复后，大教堂将散落的卧像重新聚集——一个死去君主制的石头议会。",
