    fullDescription: "In the small Lorraine village of Domrémy, around 1412, Joan of Arc was born to a modest farming family; her plain stone birth-house still stands, one of the oldest domestic buildings in France. It was in the fields and beside the village church here that, from about age 13, she said she heard the voices of Saints Michael, Catherine and Margaret commanding her to drive the English from France and see the dauphin crowned. From this obscure corner of a contested frontier she set out in 1428 on the journey that would take her to Chinon, Orléans, Reims—and ultimately the stake at Rouen. A 19th-century basilica now crowns the hill above her home.",
    fullDescriptionZh: "在洛林小村栋雷米，约1412年，贞德出生于一个普通农家；她朴素的石头出生屋至今仍在，是法国最古老的民居之一。正是在这里的田野和村教堂旁，从约13岁起，她说自己听到圣米迦勒、圣加大肋纳和圣玛加利大的声音，命她将英国人赶出法国、见证王太子加冕。从这个争议边境的偏僻角落，她1428年踏上旅程，前往希农、奥尔良、兰斯——最终走向鲁昂的火刑柱。一座19世纪的大教堂如今冠于她家上方的山丘。",
