    description: "The mountaintop where 200 Cathars chose the flames rather than renounce their faith.",
    descriptionZh: "山巅之上，200名卡特里派信徒宁赴烈火也不肯放弃信仰。",
    fullDescription: "Perched on a dizzying 1,200-metre rock spur in the Pyrenean foothills, the fortress of Montségur became the last great stronghold of the Cathars, a dualist Christian sect declared heretical and hunted in the Albigensian Crusade. After a Cathar raiding party murdered inquisitors in 1242, royal and Church forces laid siege to Montségur for ten grueling months. When it finally fell in March 1244, more than 200 Cathars who refused to renounce their faith were burned alive at the foot of the mountain, in a field still called the Prat dels Cremats—the Field of the Burned. The ruined citadel, wreathed in legend and rumours of a Cathar 'treasure', broods over the valley still.",
    fullDescriptionZh: "蒙塞居尔要塞盘踞在比利牛斯山麓一处令人眩晕的1200米岩脊上，成为卡特里派的最后一座大堡垒，这个二元论基督教派被宣布为异端，在阿尔比十字军东征中遭到追捕。1242年一支卡特里派突袭队杀死宗教裁判官后，王室和教会军队围困蒙塞居尔长达十个艰苦的月份。1244年3月它最终陷落时，200多名拒绝放弃信仰的卡特里派信徒在山脚下被活活烧死，那片田野至今仍称「被焚者之地」。这座残破的城堡，笼罩在传说和卡特里派「宝藏」的传闻中，至今仍俯瞰着山谷。",
