    description: "A prince's château holding France's finest art collection outside the Louvre—and a legendary chef's tragedy.",
    descriptionZh: "一座亲王城堡，藏有卢浮宫之外法国最精美的艺术收藏——还有一位传奇厨师的悲剧。",
    fullDescription: "The Château de Chantilly, seat of the princely house of Condé, is one of France's grandest estates, ringed by water and set in gardens by Le Nôtre. In 1671 the great chef François Vatel, master of ceremonies for a feast the prince gave for Louis XIV and 2,000 guests, was so distraught when the fish delivery seemed to fail that he ran himself through with his sword—a suicide that became legend, and gave whipped Chantilly cream its aura. The last owner, the Duke of Aumale, filled the château with a spectacular art collection—including works by Raphael and the illuminated Très Riches Heures—and bequeathed the whole to France in 1886 on condition it never be lent out or rearranged.",
    fullDescriptionZh: "尚蒂伊城堡是孔代亲王家族的府邸，是法国最宏伟的庄园之一，被水环绕，坐落在勒诺特尔设计的花园中。1671年，伟大的厨师弗朗索瓦·瓦泰尔——亲王为路易十四及2000名宾客举办盛宴的司仪——因鱼类送货似乎失败而极度沮丧，用剑自刎——这场自杀成为传奇，也为尚蒂伊奶油添上光环。最后一任主人奥马尔公爵用一批壮观的艺术收藏填满城堡——包括拉斐尔的作品和泥金装饰的《贝里公爵的豪华时祷书》——并于1886年将整座城堡遗赠法国，条件是永不外借或重新布置。",
