    coordinates: { lat: 44.7994, lng: 1.6178 },
    description: "The vertiginous pilgrimage village clinging to a cliff, home to a miracle-working Black Madonna.",
    descriptionZh: "紧贴悬崖、令人眩晕的朝圣村庄，供奉着显灵的黑圣母。",
    fullDescription: "Rocamadour spills down a sheer 120-metre limestone cliff above the Alzou gorge in a dramatic stack of chapels, houses and a castle. From the 12th century it drew vast numbers of pilgrims to its sanctuary of the Black Madonna, a venerated wooden statue said to work miracles, and to the supposed tomb of Saint Amadour, whose miraculously preserved body was 'discovered' in 1166. Kings Henry II of England and Saint Louis of France climbed its 216 penitential steps on their knees. The rusty iron sword embedded high in the chapel rock is claimed to be Durandal, the legendary blade of Roland. Sacked in the Wars of Religion, the village revived as one of France's great pilgrimage sites.",
    fullDescriptionZh: "罗卡马杜尔沿阿尔祖峡谷上方陡峭的120米石灰岩悬崖倾泻而下，是礼拜堂、房屋和城堡的壮观叠层。从12世纪起，它吸引大量朝圣者前往黑圣母圣所——一尊据说能显灵的受崇敬木雕像——以及圣阿马杜尔的所谓陵墓，其奇迹般保存的遗体1166年被「发现」。英格兰的亨利二世和法国的圣路易曾跪着攀登其216级忏悔台阶。高嵌于礼拜堂岩石中的锈铁剑被称为罗兰传奇的宝剑「杜兰达尔」。宗教战争中被洗劫后，村庄作为法国伟大的朝圣地之一复兴。",
    historicalImage: "/images/locations/historical/rocamadour-historical.jpg",
    modernImage: "/images/locations/rocamadour.jpg",
