    fullDescription: "Set among the volcanic plugs of the Auvergne, Le Puy-en-Velay has been a major pilgrimage centre for over a millennium and one of the four great starting points of the Camino to Santiago de Compostela; Bishop Godescalc set out from here on the pilgrimage as early as 951. Its cathedral, reached by a long stair, holds a venerated Black Madonna, and a Romanesque chapel improbably crowns the needle-thin Rocher d'Aiguilhe. Towering over the town is the 16-metre cast-iron statue of Notre-Dame de France, unveiled in 1860 and forged from 213 cannon captured by the French at the siege of Sevastopol in the Crimean War—faith literally cast from the instruments of war.",
    fullDescriptionZh: "勒皮昂沃莱坐落在奥弗涅的火山岩塞之间，一千多年来一直是重要的朝圣中心，也是通往圣地亚哥-德孔波斯特拉朝圣之路的四大起点之一；戈德斯卡尔克主教早在951年就从此地出发朝圣。其大教堂需登长阶抵达，供奉着受崇敬的黑圣母，一座罗曼式礼拜堂难以置信地冠于针尖般纤细的埃吉尔岩上。俯瞰全镇的是16米高的铸铁法兰西圣母像，1860年揭幕，用法国在克里米亚战争塞瓦斯托波尔围城中缴获的213门大炮铸成——信仰真真切切用战争的器具铸成。",
