    description: "Europe's grandest canyon, whose depths were first fully explored only in 1905.",
    descriptionZh: "欧洲最宏伟的峡谷，其深处直到1905年才首次被完整探索。",
    fullDescription: "The Gorges du Verdon, carved by the turquoise Verdon river through the limestone of Provence, plunge up to 700 metres deep over some 25 kilometres, making them the grandest canyon in Europe. So forbidding and inaccessible were its depths that they remained largely unknown until 1905, when speleologist Édouard-Alfred Martel led the first full expedition through the gorge, opening it to science and eventually tourism. The trail that bears his name, the Sentier Martel, still threads the canyon floor through tunnels and ladders. In 1974 the river was dammed to form the vivid Lac de Sainte-Croix at its mouth. The gorge is now a mecca for climbers, kayakers and the vultures reintroduced to its cliffs.",
    fullDescriptionZh: "凡尔登峡谷由碧绿的凡尔登河穿过普罗旺斯的石灰岩雕凿而成，在约25公里内深达700米，是欧洲最宏伟的峡谷。其深处如此险峻难达，直到1905年洞穴学家爱德华-阿尔弗雷德·马特尔率领首支完整探险队穿越峡谷，才为科学乃至旅游打开大门，此前它几乎无人知晓。以他命名的马特尔小径至今仍穿越隧道和梯子沿峡谷谷底延伸。1974年，河流被拦坝在河口形成鲜艳的圣十字湖。峡谷如今是攀岩者、皮划艇爱好者和重新引入其悬崖的秃鹫的圣地。",
