    descriptionZh: "圣路易从零建起、用以发动十字军东征的完美城墙港口。",
    fullDescription: "In the 13th century King Louis IX—Saint Louis—wanted a Mediterranean port under direct royal control, so he founded Aigues-Mortes from nothing on the marshy Camargue coast, laying it out on a strict grid and ringing it with formidable ramparts. From this artificial harbour he twice embarked on crusade—for the Seventh Crusade in 1248 and the Eighth in 1270, on which he died of dysentery outside Tunis. The Tour de Constance served as a prison, later holding Huguenot women for decades after the revocation of the Edict of Nantes; one, Marie Durand, scratched 'RÉSISTER' into the stone during 38 years of captivity. Today the sea has retreated, but the walls survive almost intact.",
    fullDescriptionZh: "13世纪，国王路易九世——圣路易——想要一个由王室直接控制的地中海港口，于是他在卡马格沼泽海岸从无到有创建了艾格-莫尔特，以严整的网格布局，环以坚固的城墙。他两次从这个人工港口出发东征——1248年第七次十字军和1270年第八次，后者他死于突尼斯城外的痢疾。康斯坦斯塔曾作监狱，南特敕令废除后关押胡格诺派妇女数十年；其中一人玛丽·杜兰在38年囚禁中把「抵抗」刻入石头。如今海水已退去，但城墙几乎完好留存。",
