    name: "Cathédrale Sainte-Cécile, Albi",
    nameZh: "阿尔比圣塞西尔大教堂",
    type: "heritage",
    region: "France",
    year: "1480",
    coordinates: { lat: 43.9284, lng: 2.1430 },
    description: "The world's largest brick building, raised as a fortress of faith to overawe defeated heretics.",
    descriptionZh: "世界上最大的砖砌建筑，作为信仰堡垒拔地而起，以震慑被击败的异端。",
    fullDescription: "After the Albigensian Crusade crushed the Cathars of the Languedoc, the Catholic Church built the Cathedral of Sainte-Cécile in Albi—the very region that had spawned the heresy—as a towering statement of triumphant orthodoxy. Begun in 1282 and largely finished by 1480, it is the largest brick building in the world, its sheer, windowless red-brick walls rising like a fortress rather than a church, a 78-metre bell tower looming over the town. Inside, the austerity gives way to breathtaking excess: every surface is painted, including a vast late-medieval Last Judgment fresco meant to terrify the faithful into obedience. Albi, birthplace of the painter Toulouse-Lautrec, is a UNESCO World Heritage Site.",
    fullDescriptionZh: "阿尔比十字军东征镇压朗格多克的卡特里派后，天主教会在阿尔比——正是孕育异端的地区——建起圣塞西尔大教堂，作为正统胜利的高耸宣言。1282年动工，1480年大体完成，它是世界上最大的砖砌建筑，陡峭无窗的红砖墙如堡垒而非教堂般拔地而起，78米高的钟楼笼罩全镇。内部的朴素让位于惊人的奢华：每一寸表面都绘有画作，包括一幅巨大的中世纪晚期《最后审判》壁画，意在恐吓信徒服从。阿尔比是画家图卢兹-劳特累克的出生地，是联合国世界遗产。",
