    region: "France",
    year: "1185",
    coordinates: { lat: 43.9530, lng: 4.8050 },
    description: "The broken medieval bridge of the famous nursery song, half-swept away by the Rhône.",
    descriptionZh: "著名童谣中断裂的中世纪桥，一半被罗讷河冲走。",
    fullDescription: "Legend says a shepherd boy named Bénézet, guided by angels, was commanded to build a bridge across the mighty Rhône at Avignon and miraculously lifted a huge stone to prove his calling; construction began around 1177. The completed Pont Saint-Bénézet stretched some 900 metres on 22 arches, a vital crossing later used by the Avignon popes. But the Rhône's floods repeatedly smashed its arches, and after a catastrophic flood in 1668 the town gave up rebuilding it, leaving just four arches jutting into the river. Immortalised in the children's song 'Sur le pont d'Avignon', the fragment—where people danced not on but beneath the bridge, on an island—remains one of France's most beloved ruins.",
    fullDescriptionZh: "传说一个名叫贝内泽的牧童受天使指引，奉命在阿维尼翁横跨湍急的罗讷河建桥，并奇迹般地举起一块巨石以证明他的使命；工程约1177年动工。建成的圣贝内泽桥以22个拱券延伸约900米，是一条重要的通道，后来为阿维尼翁教皇所用。但罗讷河的洪水一再冲毁其拱券，1668年一场灾难性洪水后，小镇放弃重建，只留下四个拱券伸入河中。因童谣《在阿维尼翁桥上》而永垂不朽，这段残桥——人们其实是在桥下的岛上而非桥上跳舞——仍是法国最受喜爱的废墟之一。",
