    coordinates: { lat: 43.6950, lng: 7.2650 },
    description: "The seafront the wintering English built, birthplace of the Riviera and site of a modern tragedy.",
    descriptionZh: "越冬的英国人建起的海滨大道，蔚蓝海岸的发源地，也是一场现代悲剧的现场。",
    fullDescription: "In the early 19th century, wealthy English aristocrats began wintering in the mild climate of Nice, then part of the Kingdom of Sardinia. In 1822, to give work to the poor during a harsh winter, the English colony funded a seafront walkway, which locals gratefully named the 'Chemin des Anglais'—the Promenade des Anglais. It became the beating heart of the emerging Côte d'Azur, drawing royalty, writers and painters to its Belle Époque hotels like the Negresco. Nice itself became French only in 1860. On Bastille Day, 14 July 2016, the promenade was the scene of a terrorist truck attack that killed 86 people—a modern scar on this symbol of leisure and light.",
    fullDescriptionZh: "19世纪初，富有的英国贵族开始在气候温和的尼斯越冬，当时尼斯属撒丁王国。1822年，为在严冬中给穷人提供工作，英国侨民资助建造了一条海滨步道，当地人感激地将其命名为「英国人之路」——英国人漫步大道。它成为新兴蔚蓝海岸跳动的心脏，吸引王室、作家和画家来到内格雷斯科等美好年代酒店。尼斯本身直到1860年才归属法国。2016年7月14日巴士底日，漫步大道成为一场恐怖卡车袭击的现场，造成86人死亡——这一休闲与光明象征上的现代伤疤。",
