    name: "Alignements de Carnac",
    nameZh: "卡纳克巨石阵列",
    type: "historical",
    region: "France",
    year: "-4500",
    coordinates: { lat: 47.5981, lng: -3.0797 },
    description: "Over 3,000 prehistoric standing stones in vast rows, older than Stonehenge and the pyramids.",
    descriptionZh: "3000多块史前立石排成庞大行列，比巨石阵和金字塔还古老。",
    fullDescription: "Stretching across the Breton countryside near Carnac are the greatest concentration of megalithic standing stones in the world—more than 3,000 menhirs erected in long, arrow-straight parallel rows over some 4 kilometres. Raised by Neolithic peoples between roughly 4500 and 3300 BC, they predate Stonehenge and Egypt's pyramids, yet their purpose remains a genuine mystery: astronomical calendar, ritual processional way, territorial marker or ancestor cult, no one truly knows. Local legend held that they were a Roman legion turned to stone by Saint Cornelius. Nearby dolmens and burial mounds show the same builders honoured their dead in monumental stone. The alignments are among Europe's most astonishing prehistoric sites.",
    fullDescriptionZh: "在卡纳克附近的布列塔尼乡间延展着世界上最大规模的巨石群——3000多块竖石，在约4公里内排成笔直的长长平行行列。它们由新石器时代人们约公元前4500至3300年间竖立，早于巨石阵和埃及金字塔，但其用途仍是真正的谜团：天文历法、仪式游行道、领地标记还是祖先崇拜，无人真正知晓。当地传说称它们是被圣科尔内利乌斯变成石头的一支罗马军团。附近的石桌坟和墓丘表明同样的建造者以纪念碑式的石头缅怀逝者。这些阵列是欧洲最惊人的史前遗址之一。",
    historicalImage: "/images/locations/historical/alignements-de-carnac-historical.jpg",
    modernImage: "/images/locations/alignements-de-carnac.jpg",
    facts: [
      "Over 3,000 standing stones stretch some 4 kilometres",
      "They were raised between roughly 4500 and 3300 BC",
      "They predate Stonehenge and the Egyptian pyramids",
      "Their purpose remains genuinely unknown",
    ],
    factsZh: [
      "3000多块立石延伸约4公里",
      "它们约公元前4500至3300年间竖立",
      "它们早于巨石阵和埃及金字塔",
      "它们的用途至今仍是真正的谜",
    ],
    address: "Route des Alignements, 56340 Carnac, France",
    addressZh: "法国卡纳克56340区巨石阵列路",
