    year: "1944",
    coordinates: { lat: 48.6493, lng: -2.0257 },
    description: "The corsair city of privateers and explorers, rebuilt stone by stone after WWII flattened it.",
    descriptionZh: "私掠者和探险家的海盗之城，二战被夷平后一石一石重建。",
    fullDescription: "The walled granite port of Saint-Malo made its fortune from the corsairs—state-licensed privateers who preyed on enemy shipping and made the town so rich and independent it once declared itself a republic, its motto: 'Neither French nor Breton, Malouin am I'. From here Jacques Cartier sailed in 1534 to claim Canada for France. In August 1944, during its liberation, American bombardment and German demolition destroyed some 80% of the old walled town in a ferocious battle. Rather than modernise, the citizens painstakingly rebuilt the historic centre stone by stone over more than a decade, recreating the corsair city almost exactly. Its ramparts still front the tidal sea.",
    fullDescriptionZh: "圣马洛这座有城墙的花岗岩港口靠海盗致富——获国家许可的私掠者掠夺敌方船只，使小镇如此富有独立，一度自称共和国，其格言是：「不是法国人也不是布列塔尼人，我是马洛人」。1534年雅克·卡蒂埃从此地起航为法国宣称加拿大。1944年8月解放期间，美军轰炸和德军爆破在一场激战中摧毁了约80%的老城。市民没有现代化，而是历时十余年一石一石艰苦重建历史中心，几乎原样再现了海盗之城。其城墙仍面朝潮汐的大海。",
