    id: 11087,
    name: "Canadian National Vimy Memorial",
    nameZh: "维米岭加拿大国家纪念碑",
    type: "historical",
    region: "France",
    year: "1917",
    coordinates: { lat: 50.3794, lng: 2.7736 },
    description: "The ridge where four Canadian divisions attacked as one—and a nation was said to be born.",
    descriptionZh: "四个加拿大师并肩进攻的山岭——据说一个国家由此诞生。",
    fullDescription: "On 9 April 1917, Easter Monday, the four divisions of the Canadian Corps attacked together for the first time and stormed Vimy Ridge, a heavily fortified German position in northern France that the French and British had failed to take at enormous cost. Advancing behind a meticulously timed creeping barrage, the Canadians seized the ridge in days, at a cost of 3,598 killed. The victory became a defining moment of national pride, often called the birth of Canada as a nation. On the crest stands Walter Allward's soaring white memorial, unveiled in 1936, its twin pylons and mourning figures inscribed with 11,285 names of Canadians killed in France with no known grave. Preserved trenches and tunnels honeycomb the ground.",
    fullDescriptionZh: "1917年4月9日复活节星期一，加拿大军的四个师首次并肩进攻，攻占维米岭——法国北部一处坚固设防的德军阵地，法军和英军曾以巨大代价未能拿下。加拿大军跟在精确计时的徐进弹幕后推进，数日内夺取山岭，代价是3598人阵亡。这场胜利成为民族自豪的决定性时刻，常被称为加拿大作为国家的诞生。山巅矗立着沃尔特·奥尔沃德高耸的白色纪念碑，1936年揭幕，其双塔和哀悼人像铭刻着11285名在法国阵亡且无已知坟墓的加拿大人姓名。保存的战壕和隧道蜂窝般布满地面。",
    historicalImage: "/images/locations/historical/canadian-national-vimy-memorial-historical.jpg",
    modernImage: "/images/locations/canadian-national-vimy-memorial.jpg",
    facts: [
      "The four Canadian divisions attacked together for the first time on 9 April 1917",
      "They took the ridge in days where others had failed",
      "3,598 Canadians were killed in the assault",
      "The memorial bears 11,285 names of the missing",
    ],
    factsZh: [
      "四个加拿大师1917年4月9日首次并肩进攻",
      "他们数日内夺取了他人未能拿下的山岭",
      "突击中3598名加拿大人阵亡",
      "纪念碑铭刻着11285名失踪者姓名",
    ],
    address: "Chemin des Canadiens, 62580 Vimy, France",
    addressZh: "法国维米62580区加拿大人之路",
