    descriptionZh: "法国最大的哥特式大教堂，容积是巴黎圣母院的两倍。",
    fullDescription: "Built with astonishing speed between 1220 and 1288 to house the supposed head of John the Baptist—brought back from the Fourth Crusade—Amiens Cathedral is the largest Gothic church in France, its interior volume roughly twice that of Notre-Dame de Paris, its vaults soaring 42 metres. John Ruskin devoted an entire book, The Bible of Amiens, to its sculpture. Its west front, carved with hundreds of biblical figures, was originally painted in vivid colours, now recreated each evening in a spectacular light show that restores the medieval polychromy. The city of Amiens saw fierce fighting in both World Wars but its cathedral survived; it is a UNESCO World Heritage Site.",
    fullDescriptionZh: "亚眠大教堂在1220至1288年间以惊人速度建成，为供奉据说是施洗约翰的头颅——从第四次十字军东征带回——它是法国最大的哥特式教堂，内部容积约为巴黎圣母院的两倍，拱顶高耸42米。约翰·拉斯金专门写了一整本书《亚眠的圣经》来论述其雕塑。其西立面雕刻着数百个圣经人物，最初绘有鲜艳色彩，如今每晚在壮观的灯光秀中重现，恢复中世纪的多彩。亚眠城在两次世界大战中都经历激战，但其大教堂幸存；它是联合国世界遗产。",
    historicalImage: "/images/locations/historical/cathedrale-notre-dame-damiens-historical.jpg",
