    id: 11090,
    name: "Cathédrale Saint-Étienne de Bourges",
    nameZh: "布尔日圣艾蒂安大教堂",
    type: "heritage",
    region: "France",
    year: "1230",
    coordinates: { lat: 47.0820, lng: 2.3990 },
    description: "A radically original Gothic cathedral with no transept and five soaring portals.",
    descriptionZh: "一座彻底独创的哥特式大教堂，没有耳堂，拥有五座高耸的门廊。",
    fullDescription: "Bourges Cathedral, built mostly between 1195 and 1230, broke the rules of Gothic design: it has no transept, giving it a unique unbroken pyramidal silhouette, and its interior achieves a soaring, unified sweep of space by nesting a tall inner nave within lower aisles. Its five great sculpted portals across the west front, and its glorious 13th-century stained glass—among the oldest and finest in France—make it a masterpiece rivalling Chartres. The cathedral rises over a city that was a Roman capital and, in 1137, saw the wedding of the future Louis VII and Eleanor of Aquitaine. Its astronomical clock has ticked since 1424. It is a UNESCO World Heritage Site.",
    fullDescriptionZh: "布尔日大教堂大多建于1195至1230年间，打破了哥特式设计的规则：它没有耳堂，赋予它独特而不间断的金字塔轮廓，其内部通过将高耸的内殿嵌套在较低的侧廊之中，实现了高耸而统一的空间气势。其西立面的五座宏伟雕刻门廊，以及辉煌的13世纪彩色玻璃——是法国最古老最精美的之一——使它成为堪与沙特尔媲美的杰作。大教堂矗立在一座曾为罗马首府的城市之上，1137年，未来的路易七世与阿基坦的埃莉诺在此完婚。其天文钟自1424年起运转不息。它是联合国世界遗产。",
    historicalImage: "/images/locations/historical/cathedrale-saint-etienne-de-bourges-historical.jpg",
