    description: "The birthplace of Henry IV, cradled at birth in a giant tortoise shell.",
    descriptionZh: "亨利四世的出生地，出生时被摇于一只巨大的龟壳中。",
    fullDescription: "In the Béarn foothills of the Pyrenees, the Château de Pau was the birthplace, on 13 December 1553, of the future King Henry IV, the most beloved of French monarchs. Legend, carefully cultivated, holds that his lips were rubbed with garlic and moistened with Jurançon wine at birth to make him hardy, and that his cradle was a single giant sea-turtle shell, still displayed in the castle. Raised partly as a rugged country boy, Henry of Navarre grew up to end the Wars of Religion, convert famously with the quip 'Paris is worth a Mass', and issue the Edict of Nantes. Later restored by Louis-Philippe and Napoleon III, the château is a museum to the king who wished every peasant 'a chicken in the pot' on Sundays.",
    fullDescriptionZh: "在比利牛斯山贝阿恩山麓，波城堡是未来的国王亨利四世——最受爱戴的法国君主——于1553年12月13日的出生地。经精心培植的传说称，他出生时嘴唇被抹上大蒜、蘸以朱朗松葡萄酒以使其强健，其摇篮是一整只巨大的海龟壳，至今仍在城堡展出。部分作为粗犷乡下男孩养大，纳瓦拉的亨利长大后结束了宗教战争，以「巴黎值一场弥撒」的名言著名地改宗，并颁布南特敕令。后经路易-菲利普和拿破仑三世修复，城堡如今是这位希望每个农民周日「锅里有只鸡」的国王的博物馆。",
    historicalImage: "/images/locations/historical/chateau-de-pau-historical.jpg",
    modernImage: "/images/locations/chateau-de-pau.jpg",
