    nameZh: "里克维尔",
    type: "heritage",
    region: "France",
    year: "1500",
    coordinates: { lat: 48.1667, lng: 7.2981 },
    description: "The fairytale Alsatian wine village that survived five centuries and two world wars untouched.",
    descriptionZh: "童话般的阿尔萨斯葡萄酒村，历经五个世纪和两次世界大战安然无恙。",
    fullDescription: "Nestled among the vineyards of the Alsatian wine road, Riquewihr looks almost exactly as it did in the 16th century: a huddle of gaily painted, timber-framed burghers' houses, cobbled lanes, ramparts and the Dolder gate-tower of 1291, all encircled by walls. Grown rich on its prized Riesling wines, the village invested in fine stone and carved wood that has endured for half a millennium. Remarkably, Riquewihr escaped serious damage in both World Wars, even as the surrounding Alsace was fought over and changed hands between France and Germany again and again. Its perfectly preserved streetscape is often cited as an inspiration for the village in Disney's Beauty and the Beast.",
    fullDescriptionZh: "里克维尔坐落在阿尔萨斯葡萄酒之路的葡萄园间，看起来几乎与16世纪一模一样：一簇色彩明快的木框架市民住宅、鹅卵石小巷、城墙和1291年的多尔德门塔，全被城墙环绕。靠珍贵的雷司令葡萄酒致富，村庄投资于历经半个千年而不衰的精美石材和雕木。值得注意的是，里克维尔在两次世界大战中都免于严重破坏，尽管周围的阿尔萨斯反复交战、在法德之间一再易手。其完好保存的街景常被引为迪士尼《美女与野兽》中村庄的灵感来源。",
