    coordinates: { lat: 47.2564, lng: -0.0781 },
    description: "The white fairy-tale castle painted in a masterpiece of the medieval Duke of Berry.",
    descriptionZh: "这座洁白的童话城堡曾被绘入贝里公爵的中世纪杰作。",
    fullDescription: "Rising in gleaming white tuffeau stone above the Loire, the Château de Saumur was rebuilt around 1400 by Duke Louis I of Anjou and immortalised soon after in the celebrated illuminated manuscript the Très Riches Heures du Duc de Berry, whose 'September' page shows the castle in exquisite detail—turrets, weathervanes and all—above the grape harvest. Over the centuries it served as a fortress, a Protestant academy, a prison for political detainees under Louis XIV and Napoleon, and an arms depot. In June 1940 the young cadets of Saumur's cavalry school, the Cadets de Saumur, made a heroic three-day stand against the advancing Germans along the Loire, a last gesture of defiance in the fall of France.",
    fullDescriptionZh: "索米尔城堡以闪亮的白色石灰华石矗立在卢瓦尔河上，约1400年由安茹公爵路易一世重建，不久便被绘入著名的泥金手稿《贝里公爵的豪华时祷书》而不朽，其「九月」页以精美细节展现城堡——塔楼、风向标一应俱全——就在葡萄收获的上方。数百年间，它充当过要塞、新教学院、路易十四和拿破仑治下政治犯的监狱以及军械库。1940年6月，索米尔骑兵学校的年轻学员——索米尔学员——沿卢瓦尔河向推进的德军做出英勇的三天抵抗，是法国沦陷中最后的反抗姿态。",
