    year: "1417",
    coordinates: { lat: 47.1281, lng: 1.0064 },
    description: "The fortress-city with a 1,000-year keep, royal tomb of a king's mistress, and grim dungeons.",
    descriptionZh: "拥有千年主楼、国王情妇王家墓与阴森地牢的堡垒之城。",
    fullDescription: "The royal city of Loches in the Touraine is crowned by one of the finest surviving Romanesque keeps in Europe, an 11th-century donjon nearly 40 metres tall. Within its royal lodge, in 1429, Joan of Arc pressed a hesitant Charles VII to march to his coronation at Reims. The Logis Royal also holds the tomb of Agnès Sorel, the first officially recognised royal mistress in French history and a favourite of Charles VII, who died young in 1450, possibly poisoned with mercury. The castle's later dungeons were notorious: Louis XI kept prisoners in suspended iron cages, and Ludovico Sforza, Duke of Milan, died here in captivity in 1508 after covering his cell walls with paintings.",
    fullDescriptionZh: "图赖讷的洛什王城以欧洲现存最精美的罗曼式主楼之一为冠，这座11世纪的主楼高近40米。1429年，在其王家居所内，贞德敦促犹豫的查理七世前往兰斯加冕。王家居所还安放着阿涅斯·索雷尔的陵墓，她是法国史上首位得到官方承认的王室情妇、查理七世的宠妃，1450年年轻早逝，可能死于汞中毒。城堡后来的地牢臭名昭著：路易十一将囚犯关在悬挂的铁笼中，米兰公爵卢多维科·斯福尔扎1508年在此囚禁中死去，此前他把牢房墙壁画满了画。",
