    id: 11106,
    name: "Fort Boyard",
    nameZh: "博亚尔堡",
    type: "historical",
    region: "France",
    year: "1857",
    coordinates: { lat: 45.9997, lng: -1.2153 },
    description: "The lozenge-shaped sea fort that took 60 years to build—and was obsolete the moment it opened.",
    descriptionZh: "菱形海上堡垒，耗时60年建成——开放之时便已过时。",
    fullDescription: "Rising straight out of the sea between the islands of Aix and Oléron, the oval stone Fort Boyard was conceived under Louis XIV and Vauban to protect the Rochefort arsenal from the English fleet, but building a fortress on a shifting sandbank in the open Atlantic defeated engineers for generations. Work stalled repeatedly and only finished around 1857, by which time the range of naval artillery had advanced so far that the fort was useless the moment it was completed. It briefly held political prisoners, then was abandoned to the waves for a century. From 1990 it gained a wholly unexpected second life as the star set of a hit French adventure game show, broadcast worldwide, its silhouette now instantly recognisable.",
    fullDescriptionZh: "椭圆形石头博亚尔堡直接从埃克斯岛与奥莱龙岛之间的海中升起，在路易十四和沃邦时期构想，用以保护罗什福尔兵工厂免遭英国舰队攻击，但在开阔大西洋一处流动沙洲上建造要塞难倒了数代工程师。工程一再停滞，约1857年才完工，那时海军火炮射程已大为进步，使堡垒在完工之时便毫无用处。它曾短暂关押政治犯，随后被弃于波涛达一个世纪。1990年起，它获得完全出乎意料的第二次生命，成为一档热门法国冒险游戏节目的明星场景，全球播出，其轮廓如今一望即知。",
    historicalImage: "/images/locations/historical/fort-boyard-historical.jpg",
