    descriptionZh: "凡尔登最坚固的堡垒，竟被一支孤立的德军巡逻队不战而取。",
    fullDescription: "Fort Douaumont was the largest and highest fort ringing Verdun, a colossus of reinforced concrete and steel turrets thought impregnable. Yet on 25 February 1916, four days into the German offensive, a handful of German soldiers infiltrated the near-empty fort—the French garrison had been stripped to a skeleton—and captured it almost without firing a shot, a humiliation that stunned France. For eight months it became the pivot of the battle; a French counterattack finally retook it in October 1916. In May 1916 an internal explosion of stored munitions killed hundreds of German soldiers, who were sealed into a bricked-up gallery that remains their tomb. The scarred, grass-covered fort can still be entered today.",
    fullDescriptionZh: "杜奥蒙堡是环绕凡尔登最大最高的堡垒，钢筋混凝土和钢制炮塔的庞然大物，被认为坚不可摧。然而1916年2月25日，德军攻势的第四天，少数德国士兵渗入几乎空无一人的堡垒——法国守军已被抽调至骨架规模——几乎不放一枪就将其占领，这一羞辱震惊了法国。此后八个月它成为战役的枢轴；1916年10月法军反攻终于夺回。1916年5月，储存弹药的内部爆炸炸死数百名德国士兵，他们被封入一条砌死的画廊，至今仍是他们的坟墓。伤痕累累、草木覆盖的堡垒今天仍可进入。",
